              "checks": ["Identificar linhas e colunas em uma matriz dada."]
            },
            {
              "title": "Notação de matriz",
              "goal": "Reconhecer a notação geral de uma matriz com índices i e j.",
              "role": "expositor",
              "dependsOn": ["Definição de matriz"],
              "covers": ["posição a_ij", "índices"],
              "checks": ["Dada uma matriz, escrever o elemento a_23."]
            }
          ]
        },
        {
          "title": "Leitura de posição a_ij",
          "microsequences": [
            {
              "title": "Identificação de elementos",
              "goal": "Localizar um elemento específico usando sua posição (i,j).",
              "role": "praticante",
              "dependsOn": ["Notação de matriz"],
              "covers": ["posição a_ij", "leitura de matriz"],
              "checks": ["Em uma matriz 3x3, encontrar o valor de a_21."]
            },
            {
              "title": "Exercícios de posição",
              "goal": "Resolver exercícios variados de localização de elementos.",
              "role": "praticante",
              "dependsOn": ["Identificação de elementos"],
              "covers": ["posição a_ij"],
              "checks": ["Dada uma matriz, listar todos os elementos de uma linha específica."]
            }
          ]
        },
        {
          "title": "Matriz transposta",
          "microsequences": [
            {
              "title": "Definição de transposta",
              "goal": "Compreender o conceito de matriz transposta e como obtê-la.",
              "role": "expositor",
              "dependsOn": ["Notação de matriz"],
              "covers": ["matriz transposta", "linha", "coluna"],
              "checks": ["Explicar o que acontece com as linhas e colunas na transposição."]
            },
            {
              "title": "Cálculo da transposta",
              "goal": "Calcular a transposta de uma matriz dada.",
              "role": "praticante",
              "dependsOn": ["Definição de transposta"],
              "covers": ["matriz transposta"],
              "checks": ["Dada uma matriz 2x3, escrever sua transposta."]
            }
          ]
        }
      ]
    }
  ]
}

